args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?filmLater ?filmLaterLabel ?directorLater ?directorLaterLabel ?birthDateLater WHERE {
  VALUES (?f1 ?f2) {
    (dbr:Jingle_All_the_Way dbr:Pinocchio's_Revenge)
    (dbr:Pinocchio's_Revenge dbr:Jingle_All_the_Way)
  }
  ?f1 (dbo:director|dbp:director) ?d1 .
  ?f2 (dbo:director|dbp:director) ?d2 .
  ?d1 (dbo:birthDate|dbp:birthDate|dbp:birth_date) ?b1 .
  ?d2 (dbo:birthDate|dbp:birthDate|dbp:birth_date) ?b2 .
  FILTER (?b1 > ?b2)
  BIND(?f1 AS ?filmLater)
  BIND(?d1 AS ?directorLater)
  BIND(?b1 AS ?birthDateLater)
  OPTIONAL { ?filmLater rdfs:label ?filmLaterLabel . FILTER(lang(?filmLaterLabel) = 'en') }
  OPTIONAL { ?directorLater rdfs:label ?directorLaterLabel . FILTER(lang(?directorLaterLabel) = 'en') }
}

